public class Stack<T> {
	private List<T> items = new ArrayList<>();

	public void push(T item) { items.add(item); }

	public T pop() {
		if (isEmpty()) throw new EmptyStackException();
		return items.remove(items.size() - 1);
	}

	public T peek() {
		if (isEmpty()) throw new EmptyStackException();
		return items.get(items.size() - 1);
	}

	public boolean isEmpty() { return items.isEmpty(); }
}

public static long fibonacci(int n) {
	if (n <= 1) return n;
	long a = 0, b = 1;
	for (int i = 2; i <= n; i++) {
		long temp = a + b;
		a = b;
		b = temp;
	}
	return b;
}

public class LinkedList<T> {
	private Node<T> head;

	public void add(T data) {
		Node<T> node = new Node<>(data);
		if (head == null) { head = node; return; }
		Node<T> curr = head;
		while (curr.next != null) curr = curr.next;
		curr.next = node;
	}

	public int size() {
		int count = 0;
		Node<T> curr = head;
		while (curr != null) { count++; curr = curr.next; }
		return count;
	}
}

public interface Observer {
	void update(String event, Object data);
}

public class EventBus {
	private Map<String, List<Observer>> listeners = new HashMap<>();

	public void subscribe(String event, Observer obs) {
		listeners.computeIfAbsent(event, k -> new ArrayList<>()).add(obs);
	}

	public void publish(String event, Object data) {
		listeners.getOrDefault(event, List.of()).forEach(o -> o.update(event, data));
	}
}

